 'g26-55': ['P_{n,dBm}=−174+10log_{10}(10^{6})=−114','SNR_{dB}=−80−(−114)=34 ; SNR_{lin}=10^{34/10}≈2512','C=10^{6}log_{2}(1+2512)≈11.3 Mbit/s'],
