 'i25-60': ['f_{1}=frac{100π}{2π}=50 Hz ; f_{2}=frac{200π}{2π}=100 Hz','f_{s,min}=2(100)=200 Hz'],
 'd08-4': ['X_{L}=500(0.020)=10 Ω ; φ=tan^{-1}(frac{10}{10})=45°'],
