const supplemental = {
 math: [
  formula('cc','Cauchy–Riemann equations','u_{x}=v_{y} ; u_{y}=−v_{x}','For f(z)=u(x,y)+jv(x,y), subscripts are partial derivatives.','If the partial derivatives are continuous in a neighborhood and satisfy these equations there, f is analytic there.','For z², u=x²−y² and v=2xy; both conditions hold everywhere.'),
  formula('grad','Directional derivative','D_{a}f=∇f·a','a is a unit direction vector and ∇f is the gradient.','Normalize the direction vector first.','For f=x²+y² at (1,2) along +x, the derivative is 2.')
 ],
 networks: [
  formula('resonance','Series RLC resonance','ω_{0}=frac{1}{sqrt{LC}} ; Q=frac{ω_{0}L}{R}','ω₀ is angular resonant frequency; Q is dimensionless.','In a series RLC circuit, reactances cancel at ω₀.','L=1 mH and C=1 µF give ω₀≈31623 rad/s.'),
  formula('stored','Stored electrical and magnetic energy','W_{C}=frac{1}{2}CV^{2} ; W_{L}=frac{1}{2}LI^{2}','V is capacitor voltage, I is inductor current, W is energy in joules.','Use instantaneous voltage or current.','A 10 µF capacitor at 10 V stores 0.5 mJ.')
 ],
 signals: [
  formula('parseval','Fourier-domain signal energy','E=∫|x(t)|^{2}dt=∫|X(f)|^{2}df','Both integrals cover the full real line, with the transform convention based on e^(−j2πft).','Use the domain with the simpler squared magnitude.','If x(t)=1 only for 0≤t<2, the energy is 2.'),
  formula('alias','Alias of a real sinusoid','f_{alias}=|f−kf_{s}|','Choose integer k to put the result between 0 and fs/2.','Use for a single real tone sampled uniformly.','A 900 Hz tone sampled at 1 kHz aliases to 100 Hz.')
 ],
 devices: [
  formula('cond','Semiconductor conductivity','σ=q(nμ_{n}+pμ_{p})','n and p are electron and hole concentrations; µn and µp are mobilities.','Use a consistent length system for concentrations and mobility.','When electrons dominate, σ≈qnµn.'),
  formula('mass','Mass action in thermal equilibrium','np=n_{i}^{2}','ni is intrinsic carrier concentration at the same temperature.','Use the nondegenerate equilibrium model.','With ni=10¹⁰ cm⁻³ and n=10¹⁶ cm⁻³, p=10⁴ cm⁻³.')
 ],
 analog: [
  formula('rcfilter','First-order passive RC cutoff','f_{c}=frac{1}{2πRC}','R in ohms and C in farads.','For a single-pole passive RC response, the gain is 3 dB below the passband at fc.','R=1 kΩ and C=100 nF give approximately 1.59 kHz.'),
  formula('slew','Sine-wave slew-rate requirement','SR≥2πfV_{pk}','SR is the maximum output slope, f is Hz, Vpk is peak output voltage.','Check this separately from small-signal bandwidth.','A 2 V peak sine at 100 kHz requires about 1.26 V/µs.')
 ],
 digital: [
  formula('xor','Half-adder outputs','S=A⊕B ; C=A·B','A and B are input bits, S sum and C carry.','Use for adding two bits with no carry-in.','1+1 produces S=0 and C=1, representing binary 10.'),
  formula('hold','Clock hold-time budget','t_{cq,min}+t_{logic,min}≥t_{hold}','tcq,min and tlogic,min are minimum path delays.','Assumes zero clock skew and jitter. A slower clock does not repair this simple hold violation.','A path of 0.4 ns meets a 0.3 ns hold requirement.')
 ],
 control: [
  formula('damped','Damped frequency and peak time','ω_{d}=ω_{n}sqrt{1−ζ^{2}} ; T_{p}=frac{π}{ω_{d}}','ωd is in rad/s and Tp in seconds.','Use for the first peak of a standard underdamped second-order step response.','ζ=0.6 and ωn=5 rad/s give ωd=4 rad/s and Tp≈0.785 s.'),
  formula('gainmargin','Gain margin in dB','GM_{dB}=−20log_{10}|L(jω_{pc})|','ωpc is a phase-crossover frequency at −180°, and L is loop gain.','Check multiple crossovers and system stability separately when needed.','At phase crossover, |L|=0.5 gives about 6.02 dB gain margin.')
 ],
 comm: [
  formula('efficiency','Spectral efficiency','η=frac{R_{b}}{B}','Rb is payload rate in bit/s and B the specified bandwidth in Hz.','Use the same bandwidth convention when comparing two systems.','8 Mbit/s in 2 MHz gives 4 bit/s/Hz.'),
  formula('ofdma','OFDM subcarrier spacing and cyclic-prefix overhead','Δf=frac{1}{T_{u}} ; η_{CP}=frac{T_{u}}{T_{u}+T_{CP}}','Tu is the useful symbol duration and TCP the cyclic prefix.','Orthogonality uses the useful symbol interval. The prefix costs airtime.','Tu=64 µs and TCP=16 µs give 15.625 kHz spacing and 80% useful airtime.')
 ],
 em: [
  formula('skin','Skin depth in a good conductor','δ≈sqrt{frac{2}{ωμσ}}','ω is rad/s, μ permeability and σ conductivity.','Use the good-conductor approximation, σ≫ωε.','If frequency quadruples, the skin depth halves.'),
  formula('plane','Time-average power density of a uniform plane wave','S_{avg}=frac{|E_{pk}|^{2}}{2η}','Epk is peak electric-field amplitude, η is real wave impedance.','Use for a uniform traveling wave in a lossless medium.','In air, Epk=10 V/m gives about 0.133 W/m².')
 ],
 apt: [
  formula('interest','Compound growth','A=P(1+r)^{n}','P is starting value, r is the fractional rate per period and n is the number of periods.','Use a constant rate with growth applied to the updated value each period.','A starting value of 100 growing 10% twice becomes 121.'),
  formula('ratios','Splitting a total in a ratio','x=frac{a}{a+b}T ; y=frac{b}{a+b}T','T is the total and a:b is the required ratio.','Scale the ratio so its shares add to the total.','A total of 50 split 2:3 gives 20 and 30.')
 ]
};
